/* Numera Academy — Moldura do site: barra do topo, menu do celular, rodapé, títulos e a ligação com o Treino.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Moldura ---------- */
const LINKS=[['home','Início'],['academy','Trilhas'],['cases','Missões'],['listas','Listas'],['jogos','Jogos'],['treino','Treino'],['lab','Terminal']];
const isActive=id=>s.page===id||s.page==='course'&&id==='academy'||s.page==='case'&&id==='cases'||s.page==='relampago'&&id==='jogos';
function topbar(){const r=dueAll();return `<header class="topbar"><div class="topbar-inner"><a class="brand" href="#home" aria-label="Numera Academy, início"><span class="brand-mark" aria-hidden="true">∑</span><span class="brand-word">numera</span></a><nav class="top-links" aria-label="Principal">${LINKS.map(([id,name])=>`<button type="button" data-act="nav" data-page="${id}" class="top-link ${isActive(id)?'active':''}" ${isActive(id)?'aria-current="page"':''}>${name}</button>`).join('')}</nav><div class="top-meta"><button type="button" class="chip" data-act="nav" data-page="review" title="Caderno de revisão">${icon('review')}<span class="chip-label">Revisão</span>${r?`<b class="count">${r}</b>`:''}</button><button type="button" class="chip flame" data-act="nav" data-page="progress" title="${P.streak(p)} dias de sequência">${icon('flame')}<b>${P.streak(p)}</b></button><button type="button" class="chip coins" data-act="nav" data-page="progress" title="Moedas: troque no camarim, na página Progresso">${coinChip('in-chip')}</button><button type="button" class="chip dark" data-act="${totalDone()?'nav':'course'}" ${totalDone()?'data-page="progress"':`data-id="${nextMethod().id}"`}>${totalDone()?`✦ <b>${p.xp}</b> XP`:'Começar'}</button></div></div></header>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Navegação no celular">${[['home','Início'],['academy','Trilhas'],['listas','Listas'],['jogos','Jogos'],['treino','Treino'],['lab','Terminal'],['progress','Perfil']].map(([id,label])=>`<button type="button" data-act="nav" data-page="${id}" class="${isActive(id)?'active':''}">${icon(id==='progress'?'user':id)}<span>${label}</span></button>`).join('')}</nav>`;}
function footer(){const col=(t,items)=>`<div class="footer-col"><h3>${t}</h3>${items.map(([id,name])=>`<button type="button" data-act="nav" data-page="${id}">${name}</button>`).join('')}</div>`;return `<footer class="site-footer"><div class="wrap footer-inner"><div class="footer-brand"><span class="brand-mark" aria-hidden="true">∑</span><strong>numera</strong><p>Métodos numéricos para Modelagem Computacional, em lições interativas.</p></div>${col('Aprender',[['academy','Trilhas'],['cases','Missões'],['listas','Listas'],['jogos','Jogos'],['treino','Treino']])}${col('Ferramentas',[['lab','Terminal'],['review','Revisão'],['progress','Progresso']])}<div class="footer-col"><h3>Referências</h3><a href="https://fncbook.com/newton/" target="_blank" rel="noopener">Driscoll &amp; Braun — Newton</a><a href="https://fncbook.com/secant/" target="_blank" rel="noopener">Secante e Bisseção</a><a href="https://www.netlib.org/linalg/html_templates/node14.html" target="_blank" rel="noopener">Netlib — Gauss-Seidel</a></div>${installEvt?`<div class="footer-install">${btn(icon('arrow')+' Instalar como app','install','ghost')}<span>Fica na tela inicial e abre mesmo sem internet.</span></div>`:''}<p class="footer-note">Projeto educacional de Modelagem Computacional. As trilhas e o Terminal cobrem raízes e sistemas lineares; as Listas trazem também ponto flutuante, interpolação, ajuste, integração e EDO. Dados e cálculos ficam no seu navegador; só as aulas em vídeo, quando você as abre, vêm do YouTube. Versão 13.</p></div></footer>`;}
const heading=(eyebrow,title,subtitle,extra='')=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1 class="display">${title}</h1><p class="lead">${subtitle}</p></div>${extra?`<div class="page-head-extra">${extra}</div>`:''}</div>`;
const bar=(v,max=100,label='Progresso')=>`<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${v}" aria-label="${label}"><span style="width:${max?Math.min(100,v/max*100):0}%"></span></div>`;
/* Aba Treino (treino.js): recebe os utilitários da interface e devolve a página. */
function openInLab(cfg){clearInputs();s.source=cfg.source;s.mode=cfg.mode;s.algorithm=cfg.algorithm||'auto';s.g='';for(const k of ['a','b','x0','x1','g'])if(cfg[k]!==undefined&&cfg[k]!==null)s[k]=String(cfg[k]);if(cfg.initial!==undefined)s.initial=cfg.initial;s.result=null;s.error='';s.help=false;s.historyOpen=false;navigate('lab');}
const TR=window.NumeraTreinoUI?window.NumeraTreinoUI({safe,icon,btn,tag,bar,method,heading,tabs:(...a)=>tabs(...a),parseAnswer:v=>parseAnswer(v),openInLab,storage,render:()=>render(),nav:page=>{s.reviewId=null;navigate(page);},announce,focus:focusSoon}):null;
function treinoCard(){if(!TR)return '';const t=TR.summary();return `<section class="card tr-progress"><span class="symbol small tone-newton" aria-hidden="true">${icon('treino')}</span><div><h3>Treino de diagnóstico</h3><p>${t.solved}/${TR.count} resolvidos sozinho · ${t.helped} vistos com ajuda · ${t.perfect} perfeitos ★ · ${t.rate===null?'nenhum diagnóstico ainda':t.rate+'% de diagnósticos certeiros'}${t.lastExam?` · última prova: ${t.lastExam.nota.toFixed(1).replace('.',',')}`:''}${t.reviewDue?` · ${t.reviewDue} para revisar`:''}</p></div>${btn('Abrir o Treino '+icon('arrow'),'nav','ghost','data-page="treino"')}</section>`;}

